:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-mist-panel: #f6f6f6;
  --color-fog-surface: #f7f7f7;
  --color-jet-bar: #1f1f1f;
  --color-onyx-backdrop: #000000;
  --color-plum-ink: #20192b;
  --color-graphite-text: #333333;
  --color-pewter-caption: #999999;
  --color-ash-border: #d9d9d9;
  --color-amethyst-glow: #594ff4;

  /* Typography — Font Families */
  --font-aeonik: "Aeonik", "Satoshi", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-aeonik-mono: "Aeonik Mono", "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.667;
  --tracking-small: 0.8px;
  --text-caption: 12px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.143;
  --tracking-body-sm: 0px;
  --text-body: 14px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.3;
  --tracking-subheading: 0px;
  --text-heading: 32px;
  --leading-heading: 1.15;
  --tracking-heading: 0px;
  --text-display: 48px;
  --leading-display: 1.05;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-36: 36px;
  --spacing-44: 44px;
  --spacing-48: 48px;
  --spacing-96: 96px;
  --spacing-144: 144px;

  /* Layout */
  --layout-page-max-width: 1224px;
  --layout-section-gap: 96px;
  --layout-card-padding: 0px;
  --layout-element-gap: 12px;

  /* Border Radius */
  --radius-sm: 1px;
  --radius-md: 4px;

  /* Named Radii */
  --radius-buttons: 4px;
  --radius-cards: 4px;
  --radius-images: 4px;
  --radius-small-elements: 1px;
  --radius-nav: 0px;
  --radius-sections: 0px;

  /* Shadows */
  /* none — the system is shadowless; elevation is tonal */

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-mist-panel: #f6f6f6;
  --surface-fog-surface: #f7f7f7;
  --surface-jet-bar: #1f1f1f;
  --surface-onyx-backdrop: #000000;
}

